{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Zalcitabine, a small polar dideoxycytidine nucleoside, had an absolute oral bioavailability of 80% in HIV-infected men, demonstrating that nucleoside analogs can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "In fasting patients with advanced HIV infection, zalcitabine tablets had absolute bioavailability of 80% (range 54–127%), directly matching the fasted condition and supporting F ≥ 20% for a nucleoside analog.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Didanosine, a purine dideoxynucleoside, had a median F of 0.28 (28%) in fasting patients, above the 20% threshold; its lower fed values are not applicable to the fasted query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Didanosine given as a solution with antacid to fasting patients had oral bioavailability of 38% ± 15%, again supporting F ≥ 20% for a purine nucleoside under fasting conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "OGT 719, a polar fluorinated pyrimidine nucleoside, had overall oral bioavailability around 25% in patients, above the 20% threshold despite being a nucleoside with considerable polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A pyrazolopyrimidinone with a sulfonamide-piperazine side chain had 34% bioavailability in fasted healthy volunteers, supporting that even moderately polar heterocycles exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a carbocyclic guanine nucleoside. The most transferable human evidence, including absolute bioavailability measurements for nucleoside analogs under fasting conditions, consistently shows F ≥ 20% (zalcitabine 80%, didanosine 22–38%, OGT719 ~25%). No affirmative fasted-state evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The exact carbocyclic guanine nucleoside scaffold is not represented among the evidence molecules, so transfer relies on related nucleoside analogs.",
    "Fasted-state data are available for some nucleoside analogs, but not for a molecule with the same two-hydroxymethyl cyclopentane substitution pattern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

